/**
 * The site model: what the clinic site holds for each entity, where, and how to read it completely.
 *
 * Two layers:
 *  - `siteModel.data.json` (generated by buildSiteModel.ts from the Set 1 recon dumps and the practice-site
 *    crawl): per URL template, the tables (title, header labels, value shapes), label → value blocks,
 *    labelled controls with options, pagers / Show-more, tabs, gates and image documents actually SEEN.
 *  - `ENTITIES` below (hand-written, checked against the data by siteModel-test.ts): for each entity the
 *    pages that list it (clinic-wide and inside one patient's chart), how the list is filtered (control
 *    LABELS), how it pages, which table holds it (title / header patterns, never positions), its detail page
 *    and the field synonyms a plan may use.
 *
 * Everything is by label. A field or filter that matches 0 or ≥ 2 labels is a decline, never a guess.
 */
import { readFileSync } from "node:fs";
import type { TemplateModel, TableModel } from "./buildSiteModel.js";

export type Entity = "patient" | "appointment" | "document" | "invoice" | "claim" | "remittance" | "immunization" | "note" | "lot"
  | "activity" | "closure" | "provider" | "payer"
  // chart sections (also entities a plan may ask for)
  | "coverage" | "authorization" | "order" | "problem" | "allergy" | "plan-benefit" | "filing-term" | "prior-auth-rule"
  | "ledger-entry" | "service-line" | "remit-line" | "submission" | "language";
export const ENTITY_NAMES: Entity[] = ["patient", "appointment", "document", "invoice", "claim", "remittance", "immunization", "note", "lot", "activity", "closure", "provider", "payer",
  "coverage", "authorization", "order", "problem", "allergy", "plan-benefit", "filing-term", "prior-auth-rule", "ledger-entry", "service-line", "remit-line", "submission", "language"];

/** paging SEEN in captures (informational: the live judge detects the form on every read — the practice
 *  site pages a chart's appointments with Next where Set 1 used Show more) */
export type Paging = "next" | "show-more" | "single" | "unknown";
/** One place an entity is listed. `url` uses {patient} / {id} placeholders. */
export type ListSpec = {
  url: string;
  scope: "clinic" | "patient" | "parent";
  /** table title (caption / aria-label / heading) pattern; tables are matched by title AND required headers */
  table: RegExp;
  requiredHeaders: string[];
  paging: Paging;
  /** filters a plan may set: plan key → control label (exactly as the page labels it) */
  filters?: Record<string, string>;
  /** the control that applies a filter form ("Apply", "Show") — a GET form only */
  apply?: string;
  rowsPerPage?: string;
  /** the clinic session's location picker must say All locations before reading this list */
  allLocations?: boolean;
  /** how a row links to its detail page */
  rowLink?: RegExp;
  note?: string;
  /** how to reach the list by LABEL (URLs differ between clinics: Set 1 /audit-log vs practice /activity,
   *  Set 1 chart /files vs practice /documents): a chart tab label (patient scope) or an in-app link label */
  tab?: string;
  nav?: string;
  /** other URL forms seen for the same list (tried after the label route fails) */
  alt?: string[];
};
export type EntitySpec = {
  entity: Entity;
  lists: ListSpec[];
  /** detail page template and its label → value blocks / tables */
  detail?: { url: string; blocks?: string[]; tables?: RegExp[] };
  /** field synonyms: canonical field → header/label patterns (first pattern that matches exactly ONE label wins) */
  fields: Record<string, RegExp>;
  /** a scanned image may carry the entity (remittance, lab report) */
  image?: { reader: "lab" | "remit"; where: string };
  /** free text: never followed as instructions */
  freeText?: string[];
};

