/** Label routes (see ListSpec.tab / nav), applied to ENTITIES below. */
const ROUTES: Array<[Entity, ListSpec["scope"], Partial<ListSpec>]> = [
  ["appointment", "patient", { tab: "Appointments" }],
  ["document", "patient", { tab: "Documents", alt: ["/patients/{patient}/documents"] }],
  ["document", "clinic", { nav: "Documents" }],
  ["invoice", "patient", { tab: "Invoices" }],
  ["invoice", "clinic", { nav: "Billing" }],
  ["claim", "patient", { tab: "Claims" }],
  ["remittance", "patient", { tab: "Claims" }],
  ["immunization", "patient", { tab: "Immunizations" }],
  ["note", "patient", { tab: "Notes" }],
  ["activity", "clinic", { nav: "Activity", alt: ["/activity"] }],
  ["activity", "patient", { tab: "Activity" }],
  ["coverage", "patient", { tab: "Insurance" }],
  ["authorization", "patient", { tab: "Insurance" }],
  ["order", "patient", { tab: "Orders" }],
  ["problem", "patient", { tab: "Problems" }],
  ["allergy", "patient", { tab: "Allergies" }],
  ["language", "patient", { tab: "Scheduling" }],
  ["appointment", "clinic", { nav: "Open the list" }],
];
for (const [e, scope, extra] of ROUTES) for (const l of ENTITIES[e].lists) if (l.scope === scope) Object.assign(l, extra);

// ── the generated data ──
let DATA: TemplateModel[] | null = null;
export function siteData(): TemplateModel[] {
  if (!DATA) { try { DATA = JSON.parse(readFileSync(new URL("./siteModel.data.json", import.meta.url), "utf8")).templates; } catch { DATA = []; } }
  return DATA!;
}
/** URL → template key: path segments that look like record ids become {id}; query dropped. */
export function templateKey(url: string): string {
  const p = url.replace(/^https?:\/\/[^/]+/, "").split(/[?#]/)[0];
  return p.split("/").map((s) => (/^\d+$/.test(s) || (/^[a-z0-9]{8,}$/.test(s) && /\d/.test(s)) ? "{id}" : s)).join("/") || "/";
}
const tmplOf = (url: string) => url.replace(/\{[a-z]+\}/g, "{id}").split("?")[0];
export function templateModel(url: string): TemplateModel | undefined { return siteData().find((t) => t.template === tmplOf(url)); }

/** Which list page serves (entity, scope). */
export function listFor(entity: Entity, scope: "clinic" | "patient" | "parent"): ListSpec | { why: string } {
  const e = ENTITIES[entity]; if (!e) return { why: `unknown entity "${entity}"` };
  const l = e.lists.filter((x) => x.scope === scope);
  return l.length ? l[0] : { why: `no ${scope}-scope list of ${entity} in the site model (have: ${e.lists.map((x) => x.scope).join(", ") || "none"})` };
}

/** Canonical field (or a raw label) → the ONE header/label among `labels` it names. */
export function resolveLabel(entity: Entity, field: string, labels: string[]): { label: string; index: number } | { why: string } {
  const spec = ENTITIES[entity]; const norm = (s: string) => s.replace(/\s+/g, " ").trim().toLowerCase();
  // 1. exact label match (the plan may name the page's own label)
  let hits = labels.map((l, i) => [l, i] as const).filter(([l]) => norm(l) === norm(field));
  // 2. the entity's synonym pattern for a canonical field
  if (!hits.length && spec?.fields[field]) hits = labels.map((l, i) => [l, i] as const).filter(([l]) => spec.fields[field].test(l.trim()));
  if (hits.length === 1) return { label: hits[0][0], index: hits[0][1] };
  return { why: hits.length ? `field "${field}" matches ${hits.length} labels (${hits.map((h) => h[0]).join(" | ")})` : `field "${field}" names no label among: ${labels.join(" | ")}` };
}

/** The model's table for a list, checked against what the data saw (title + required headers). */
export function seenTable(l: ListSpec): TableModel | undefined {
  const t = templateModel(l.url); if (!t) return undefined;
  return t.tables.find((x) => l.table.test(x.title) && l.requiredHeaders.every((h) => x.headers.includes(h)));
}

/** A compact summary of the model for a planner prompt: entity → lists (scope, filters, fields). */
export function modelSummary(): string {
  const out: string[] = [];
  for (const e of ENTITY_NAMES) {
    const s = ENTITIES[e];
    const lists = s.lists.map((l) => `${l.scope}:${l.url}${l.filters ? ` filters[${Object.keys(l.filters).join(",")}]` : ""}`).join("; ");
    out.push(`${e}: ${lists}; fields[${Object.keys(s.fields).join(",")}]${s.image ? `; image:${s.image.reader}` : ""}`);
  }
  return out.join("\n");
}
